<?php
namespace App\Http\Controllers;
use App\Models\OvertimeRequest;
use Illuminate\Http\RedirectResponse;
use Illuminate\Http\Request;
use Illuminate\View\View;
class OvertimeRequestController extends EmployeeController { public function index(): View { return view('employee.overtime.index',['requests'=>OvertimeRequest::where('karyawan_id',$this->employee()->id)->latest('tanggal')->get()]); } public function create(): View { return view('employee.overtime.form',['requestItem'=>new OvertimeRequest()]); } public function store(Request $request): RedirectResponse { $data=$this->validateRequest($request); OvertimeRequest::create($data+['karyawan_id'=>$this->employee()->id,'status'=>'Pending']); return redirect()->route('overtime-requests.index')->with('success','Permintaan lembur berhasil dikirim.'); } public function edit(OvertimeRequest $overtime_request): View { $this->owned($overtime_request); abort_unless($overtime_request->status==='Pending',403); return view('employee.overtime.form',['requestItem'=>$overtime_request]); } public function update(Request $request, OvertimeRequest $overtime_request): RedirectResponse { $this->owned($overtime_request); abort_unless($overtime_request->status==='Pending',403); $overtime_request->update($this->validateRequest($request)); return redirect()->route('overtime-requests.index')->with('success','Permintaan lembur diperbarui.'); } public function destroy(OvertimeRequest $overtime_request): RedirectResponse { $this->owned($overtime_request); abort_unless($overtime_request->status==='Pending',403); $overtime_request->delete(); return back()->with('success','Permintaan lembur dihapus.'); } private function validateRequest(Request $r): array{return $r->validate(['tanggal'=>'required|date','jam_mulai'=>'required|date_format:H:i','jam_selesai'=>'required|date_format:H:i|after:jam_mulai','keperluan'=>'required|string|max:2000']);} private function owned(OvertimeRequest $item):void {abort_unless($item->karyawan_id===$this->employee()->id,404);} }
